var _b=(typeof baseUrl!=='undefined'&&baseUrl)?String(baseUrl):'';
var _pre='[]';
try{
if(typeof result==='string'&&result.indexOf('"media"')>=0){
var _j=JSON.parse(result);
var _med=(_j&&_j.media)?_j.media:[];
var _out=[];
for(var _i=0;_i<_med.length;_i++){
var _m=_med[_i];
if(!_m||_m.type!=='video'){continue;}
var _v=_m.video_url?String(_m.video_url):'';
if(!_v){continue;}
var _u='',_h='';
if(_v.indexOf('.m3u8')>=0){_h=_v;}else{_u=_v;}
_out.push({t:_m.title?String(_m.title):'',c:_m.thumbnail?String(_m.thumbnail):'',u:_u,h:_h});
}
if(_out.length){_pre=JSON.stringify(_out);}
}
}catch(_e){}
_pre=_pre.replace(/<\//g,'<\\/');
var CSS=`html,body{margin:0;padding:0;height:100%;background:#000;overflow:hidden;font-family:-apple-system,Roboto,sans-serif}#vp{position:fixed;left:0;top:0;right:0;bottom:0;overflow:hidden;touch-action:none}#stack{will-change:transform}.slide{position:relative;height:100vh;width:100vw;overflow:hidden;background:#0a0a0a}.slide .ph{position:absolute;left:0;top:0;right:0;bottom:0;display:flex;align-items:center;justify-content:center;background:#0a0a0a}.slide .ph img{max-width:100%;max-height:100%;object-fit:contain}.slide video.vd{position:absolute;left:0;top:0;width:100%;height:100%;object-fit:contain;object-position:top;background:#000}.slide .meta{position:absolute;left:0;right:0;bottom:0;min-height:52px;max-height:86px;overflow:hidden;padding:9px 14px;background:#000;display:flex;align-items:center;z-index:3;pointer-events:none}.slide .meta h3{margin:0;font-size:15px;line-height:1.45;color:#fff;font-weight:500;text-shadow:0 1px 3px rgba(0,0,0,.8)}#bar{position:fixed;left:0;right:0;top:0;z-index:12;color:#fff;font-size:12px;text-align:center;padding:6px;background:rgba(0,0,0,.5)}#pwrap{position:fixed;left:22px;right:22px;bottom:94px;height:4px;background:rgba(255,255,255,.24);border-radius:2px;z-index:20;pointer-events:none;opacity:0;transition:opacity .25s}#pbar{height:100%;width:0;background:#e0407a;border-radius:2px;box-shadow:0 0 6px rgba(224,64,122,.55)}#idx{position:fixed;right:10px;top:40px;z-index:20;color:#fff;font-size:12px;background:rgba(0,0,0,.5);padding:3px 9px;border-radius:11px;pointer-events:none}`;
var CORE=`window.onerror=function(m){var b=document.getElementById('bar');if(b){b.style.display='block';b.textContent='JS错误: '+m;}};
var ORIGIN='https://swipefap.com';
var vp=document.getElementById('vp'),stack=document.getElementById('stack'),bar=document.getElementById('bar'),pbar=document.getElementById('pbar'),idx=document.getElementById('idx'),pwrap=document.getElementById('pwrap');
var page=0,loading=false,ended=false,slides=[],cur=0,total=0;
function parseItems(txt){
var out=[];
try{
var j=JSON.parse(txt);
var med=(j&&j.media)?j.media:[];
for(var i=0;i<med.length;i++){
var m=med[i];
if(!m||m.type!=='video'){continue;}
var v=m.video_url?String(m.video_url):'';
if(!v){continue;}
var u='',h='';
if(v.indexOf('.m3u8')>=0){h=v;}else{u=v;}
out.push({t:m.title?String(m.title):'',c:m.thumbnail?String(m.thumbnail):'',u:u,h:h});
}
}catch(e){}
return out;
}
var catBase=String(CATBASE||'');
if(catBase.indexOf('swipefap.com')<0){catBase=String(location.href||'').split('?')[0].split('#')[0];}
if(catBase.indexOf('swipefap.com')<0){catBase=ORIGIN+'/';}

function hideBar(){if(bar){bar.style.display='none';}}
function showBar(t){if(bar){bar.style.display='block';bar.textContent=t;}}
var ctlTimer=null;
function setCtl(v){if(!pwrap){return;}pwrap.style.opacity=v?'1':'0';}
function showCtl(keep){setCtl(1);if(ctlTimer){clearTimeout(ctlTimer);ctlTimer=null;}if(!keep){ctlTimer=setTimeout(function(){setCtl(0);},3000);}}
function addSlides(items){
for(var i=0;i<items.length;i++){(function(it){
var slide=document.createElement('div');slide.className='slide';
if(it.c){var ph=document.createElement('div');ph.className='ph';var img=document.createElement('img');img.src=it.c;img.onerror=function(){ph.style.display='none';};ph.appendChild(img);slide.appendChild(ph);}
var v=document.createElement('video');v.className='vd';v.loop=true;v.preload='metadata';v.muted=true;v.poster=it.c||'';v.setAttribute('playsinline','');v.setAttribute('webkit-playsinline','');v.setAttribute('x5-playsinline','');v.setAttribute('x5-video-player-type','h5');if(it.h){var so=document.createElement('source');so.src=it.h;so.type='application/x-mpegURL';v.appendChild(so);v.addEventListener('error',function(){if(!it._err){it._err=1;var m=document.createElement('div');m.style.cssText='position:absolute;left:0;right:0;top:44%;text-align:center;color:#fff;font-size:13px;text-shadow:0 1px 4px #000;pointer-events:none';m.textContent='该条为 HLS 流，本机若无法播放请上滑跳过';slide.appendChild(m);}});}
slide.appendChild(v);
var meta=document.createElement('div');meta.className='meta';var h3=document.createElement('h3');h3.textContent=it.t||'';meta.appendChild(h3);slide.appendChild(meta);
stack.appendChild(slide);slides.push({el:slide,vid:v,url:it.u,hls:it.h||'',loaded:false});
})(items[i]);}
total=slides.length;updateIdx();
}
function updateIdx(){if(idx){idx.textContent=total?((cur+1)+'/'+total+(ended?'':'+')):'';}}
function updateProgress(){var v=slides[cur]?slides[cur].vid:null;if(!v||!isFinite(v.duration)||v.duration<=0){if(pbar){pbar.style.width='0%';}return;}if(pbar){pbar.style.width=((v.currentTime/v.duration)*100).toFixed(2)+'%';}}
setInterval(updateProgress,300);
function playAt(n){
if(n<0){n=0;}if(n>=total){n=total-1;}
for(var k=0;k<slides.length;k++){if(k!==n&&slides[k].vid){try{slides[k].vid.pause();}catch(e){}}}
cur=n;stack.style.transition='transform .38s cubic-bezier(.22,.61,.36,1)';stack.style.transform='translateY('+(-n*100)+'vh)';
var it=slides[n];
if(it&&!it.loaded&&it.url){it.vid.src=it.url;it.loaded=true;try{it.vid.load();}catch(e){}var p=it.vid.play();if(p&&p.catch){p.catch(function(){});}}
else if(it&&it.vid&&it.hls&&!it.loaded){it.loaded=true;try{it.vid.load();}catch(e){}var hp=it.vid.play();if(hp&&hp.catch){hp.catch(function(){});}}
else if(it&&it.vid){var q=it.vid.play();if(q&&q.catch){q.catch(function(){});}}
updateIdx();updateProgress();
if(n>=total-3){loadMore();}
}
function pageUrl(n){
var u=catBase,i=u.indexOf('page=');
if(i>=0){var j=i+5,k=j;while(k<u.length){var c=u.charAt(k);if(c>='0'&&c<='9'){k++;}else{break;}}return u.substring(0,i)+'page='+n+u.substring(k);}
return u+(u.indexOf('?')>=0?'&':'?')+'page='+n;
}
function fetchPage(url,ok,err){
try{var x=new XMLHttpRequest();x.open('GET',url,true);x.onload=function(){if(x.status>=200&&x.status<400){ok(parseItems(x.responseText));}else{err('HTTP'+x.status);}};x.onerror=function(){err('net');};x.send();}catch(e){err('xhr');}
}
function loadMore(){
if(loading||ended){return;}loading=true;
fetchPage(pageUrl(page+1),function(items){
loading=false;
if(items.length===0){ended=true;updateIdx();return;}
page=page+1;addSlides(items);if(items.length<3){ended=true;}updateIdx();
},function(e){loading=false;ended=true;updateIdx();});
}
function retry(){if(vp){vp.addEventListener('click',function once(){vp.removeEventListener('click',once);loadFirst();});}}
function loadFirst(){
if(loading){return;}loading=true;showBar('加载中…');
fetchPage(catBase,function(items){
loading=false;
if(items.length){hideBar();page=1;addSlides(items);playAt(0);showCtl();loadMore();}
else{showBar('未取到视频·点屏重试');retry();}
},function(e){loading=false;showBar('加载失败('+e+')·点屏重试');retry();});
}
var sy=0,sx=0,mode=null,busy=false,startTime=0;
function getXY(e){
try{
var t=null;
if(e.touches&&e.touches.length){t=e.touches[0];}
else if(e.changedTouches&&e.changedTouches.length){t=e.changedTouches[0];}
if(t&&typeof t.clientX==='number'){return {x:t.clientX,y:t.clientY};}
if(typeof e.clientX==='number'){return {x:e.clientX,y:e.clientY};}
}catch(_){}
return {x:sx,y:sy};
}
function snap(){if(stack){stack.style.transition='transform .3s cubic-bezier(.22,.61,.36,1)';stack.style.transform='translateY('+(-cur*100)+'vh)';}}
function onStart(e){
try{
var p=getXY(e);sy=p.y;sx=p.x;mode=null;busy=true;showCtl(true);
if(stack){stack.style.transition='none';}
var v=slides[cur]?slides[cur].vid:null;
if(v){startTime=v.currentTime;try{v.muted=false;}catch(_){}}
}catch(_){busy=false;mode=null;snap();}
}
function onMove(e){
try{
if(!busy){return;}
var p=getXY(e);var dy=p.y-sy,dx=p.x-sx;
if(mode===null){
if(Math.abs(dy)>8||Math.abs(dx)>8){
mode=Math.abs(dx)>Math.abs(dy)?'seek':'slide';
if(mode==='seek'){var vv=slides[cur]?slides[cur].vid:null;if(vv){try{vv.pause();}catch(_){}}showCtl(true);}
}
}
if(mode==='slide'){if(stack){stack.style.transform='translateY(calc('+(-cur*100)+'vh + '+dy+'px))';}}
else if(mode==='seek'){var v=slides[cur]?slides[cur].vid:null;if(v&&isFinite(v.duration)&&v.duration>0){var nt=Math.max(0,Math.min(startTime+(dx/v.clientWidth)*v.duration,v.duration));try{v.currentTime=nt;}catch(_){}if(pbar){pbar.style.width=((nt/v.duration)*100).toFixed(2)+'%';}}}
}catch(_){mode='slide';snap();}
}
function onEnd(e){
try{
if(!busy){return;}busy=false;
var p=getXY(e);var dy=p.y-sy,dx=p.x-sx;
if(mode==='slide'){if(dy<-60&&cur<total-1){playAt(cur+1);}else if(dy>60&&cur>0){playAt(cur-1);}else{playAt(cur);}}
else if(mode==='seek'){var v=slides[cur]?slides[cur].vid:null;if(v){var pp=v.play();if(pp&&pp.catch){pp.catch(function(){});}}updateProgress();showCtl();}
else{var vv=slides[cur]?slides[cur].vid:null;if(vv){if(vv.paused){var r=vv.play();if(r&&r.catch){r.catch(function(){});}}else{vv.pause();}}showCtl();}
mode=null;
}catch(_){mode=null;snap();}
}
if(vp){
vp.addEventListener('touchstart',onStart,{passive:true});
vp.addEventListener('touchmove',onMove,{passive:true});
vp.addEventListener('touchend',onEnd,{passive:true});
vp.addEventListener('touchcancel',function(e){try{if(busy){onEnd(e);}}catch(_){busy=false;mode=null;snap();}},{passive:true});
vp.addEventListener('mousedown',onStart);
vp.addEventListener('mousemove',onMove);
vp.addEventListener('mouseup',onEnd);
}
if(ITEMS&&ITEMS.length){hideBar();page=1;addSlides(ITEMS);playAt(0);showCtl();loadMore();}
else{loadFirst();}
`;
result=`<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover"><title>swipefap</title><style>${CSS}</style></head><body><div id="bar">加载中…</div><div id="vp"><div id="stack"></div></div><div id="pwrap"><div id="pbar"></div></div><div id="idx"></div><script>var ITEMS=${_pre};var CATBASE=${JSON.stringify(_b)};${CORE}</script></body></html>`;
